' fill='#15803d'>5. Barış, Affet</text><text x='674' y='100' text-anchor='middle' font-size='10.5' fill='#14532d'>sayfayı kapat</text><text x='158' y='90' text-anchor='middle' font-size='14' fill='#64748b'>&gt;</text><text x='305' y='90' text-anchor='middle' font-size='14' fill='#64748b'>&gt;</text><text x='452' y='90' text-anchor='middle' font-size='14' fill='#64748b'>&gt;</text><text x='599' y='90' text-anchor='middle' font-size='14' fill='#64748b'>&gt;</text><rect x='20' y='145' width='170' height='120' rx='10' fill='#dbeafe'/><text x='105' y='175' text-anchor='middle' font-size='14' font-weight='bold' fill='#1e3a8a'>İSLAM</text><text x='105' y='200' text-anchor='middle' font-size='11' fill='#1e40af'>Allah'a teslimiyet,</text><text x='105' y='218' text-anchor='middle' font-size='11' fill='#1e40af'>esenlik yolu</text><rect x='207' y='145' width='170' height='120' rx='10' fill='#fef9c3'/><text x='292' y='175' text-anchor='middle' font-size='14' font-weight='bold' fill='#854d0e'>TAKVA</text><text x='292' y='200' text-anchor='middle' font-size='11' fill='#713f12'>Haksızlıktan ve</text><text x='292' y='218' text-anchor='middle' font-size='11' fill='#713f12'>kırıcılıktan sakınma</text><rect x='394' y='145' width='170' height='120' rx='10' fill='#ede9fe'/><text x='479' y='175' text-anchor='middle' font-size='14' font-weight='bold' fill='#5b21b6'>SABIR</text><text x='479' y='200' text-anchor='middle' font-size='11' fill='#4c1d95'>Öfke ve kırgınlık</text><text x='479' y='218' text-anchor='middle' font-size='11' fill='#4c1d95'>anında direnç</text><rect x='581' y='145' width='159' height='120' rx='10' fill='#0f766e'/><text x='660' y='175' text-anchor='middle' font-size='14' font-weight='bold' fill='#ffffff'>SULH</text><text x='660' y='200' text-anchor='middle' font-size='11' fill='#ccfbf1'>Toplumda barış</text><text x='660' y='218' text-anchor='middle' font-size='11' fill='#ccfbf1'>ve kardeşlik</text><text x='380' y='288' text-anchor='middle' font-size='11' fill='#475569'>Teslim olan, sakınan ve sabreden mümin barışın taşıyıcısı olur.</text></svg>"}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
